        FROM analytics.daily_revenue
        WHERE revenue_date > (SELECT max(revenue_date) FROM analytics.daily_revenue) - %s
        ORDER BY revenue_date DESC, currency
        """,
        (_int_param(parameters, "days", default=7, low=1, high=14),),
    ).fetchall()


