        "order_id": order_id, "customer_id": 1, "order_status": status, "amount": Decimal(amount),
        "currency": currency, "created_at": _AT, "updated_at": _AT,
    }  # fmt: skip


def _payment(payment_id: int, order_id: int, status: str, amount: str) -> dict:
