// Thin client for the DataTraceMind API, plus the polling hook the pages use.
import { useCallback, useEffect, useRef, useState } from "react";

const ACCESS_CODE_KEY = "dtm-access-code";

export function getAccessCode() {
  try {
    return window.localStorage.getItem(ACCESS_CODE_KEY) || "";
  } catch {
    return "";
  }
}

export function setAccessCode(code) {
  try {
    if (code) window.localStorage.setItem(ACCESS_CODE_KEY, code);
    else window.localStorage.removeItem(ACCESS_CODE_KEY);
  } catch {
    // Storage can be unavailable (private window); the code then lasts for this page only.
  }
}

export async function api(path, { method = "GET", body } = {}) {
  const headers = {};
  if (body !== undefined) headers["Content-Type"] = "application/json";
  const code = getAccessCode();
  if (code) headers["X-Demo-Access-Code"] = code;
  const response = await fetch(`/api${path}`, {
    method,
    headers,
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  let payload = null;
  try {
    payload = await response.json();
  } catch {
    // A response without a JSON body; the status code carries the outcome.
  }
  if (!response.ok) {
    const detail = payload?.detail;
    const message = Array.isArray(detail)
      ? detail.map((d) => `${d.loc?.slice(1).join(".")}: ${d.msg}`).join("; ")
      : detail || `${response.status} ${response.statusText}`;
    const error = new Error(message);
    error.status = response.status;
    throw error;
  }
  return payload;
}

// Poll `path` every `intervalMs`. Keeps the last good data while a refresh is
// in flight or failing, so the page never flashes empty.
export function usePoll(path, intervalMs = 2500) {
  const [data, setData] = useState(null);
  const [error, setError] = useState(null);
  const latest = useRef(path);
  latest.current = path;

  const refresh = useCallback(async () => {
    if (!path) return;
    try {
      const next = await api(path);
      if (latest.current === path) {
        setData(next);
        setError(null);
      }
    } catch (err) {
      if (latest.current === path) setError(err);
    }
  }, [path]);

  useEffect(() => {
    setData(null);
    setError(null);
    if (!path) return undefined;
    refresh();
    const timer = window.setInterval(refresh, intervalMs);
    return () => window.clearInterval(timer);
  }, [path, intervalMs, refresh]);

  return { data, error, refresh };
}

// Run a mutating call and expose its busy and error state to a button.
export function useAction() {
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(null);
  const run = useCallback(async (fn) => {
    setBusy(true);
    setError(null);
    try {
      return await fn();
    } catch (err) {
      setError(err.message);
      return undefined;
    } finally {
      setBusy(false);
    }
  }, []);
  return { busy, error, run, clearError: () => setError(null) };
}

// Formatting helpers shared by every page.

const LOCALE = { INR: "en-IN", USD: "en-US" };

export function money(value, currency) {
  if (value === null || value === undefined) return "–";
  return new Intl.NumberFormat(LOCALE[currency] || "en-US", {
    style: "currency",
    currency: currency || "USD",
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(value);
}

export function compactMoney(value, currency) {
  return new Intl.NumberFormat(LOCALE[currency] || "en-US", {
    style: "currency",
    currency: currency || "USD",
    notation: "compact",
    maximumFractionDigits: 1,
  }).format(value);
}

export function number(value) {
  if (value === null || value === undefined) return "–";
  return new Intl.NumberFormat("en-US").format(value);
}

export function signedMoney(value, currency) {
  const text = money(Math.abs(value), currency);
  if (value > 0) return `+${text}`;
  if (value < 0) return `−${text}`;
  return text;
}

export function clock(iso) {
  if (!iso) return "–";
  return new Date(iso).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" });
}

export function dateTime(iso) {
  if (!iso) return "–";
  return new Date(iso).toLocaleString([], {
    month: "short",
    day: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });
}

export function shortDate(isoDate) {
  const [year, month, day] = isoDate.split("-").map(Number);
  return new Date(year, month - 1, day).toLocaleDateString([], { month: "short", day: "numeric" });
}

export function ago(seconds) {
  if (seconds === null || seconds === undefined) return "never";
  if (seconds < 90) return `${Math.round(seconds)}s ago`;
  if (seconds < 5400) return `${Math.round(seconds / 60)} min ago`;
  return `${Math.round(seconds / 3600)} h ago`;
}

export function titleCase(text) {
  return (text || "").replace(/_/g, " ").replace(/^./, (c) => c.toUpperCase());
}

export function pretty(value) {
  return typeof value === "string" ? value : JSON.stringify(value, null, 2);
}

// Small building blocks used across pages.
import { titleCase } from "../format.js";

// A status is never shown by colour alone: every badge pairs a glyph with a label.
const TONE = {
  good: { glyph: "✓", label: "good" },
  warning: { glyph: "!", label: "warning" },
  serious: { glyph: "▲", label: "serious" },
  critical: { glyph: "✕", label: "critical" },
  neutral: { glyph: "•", label: "" },
  active: { glyph: "◌", label: "" },
};

const STATUS_TONE = {
  // incident lifecycle
  detected: "serious",
  investigating: "active",
  diagnosed: "active",
  repair_proposed: "active",
  validating: "active",
  validation_failed: "critical",
  awaiting_approval: "warning",
  applying: "active",
  application_failed: "critical",
  verifying: "active",
  resolved: "good",
  rejected: "neutral",
  escalated: "serious",
  // severities
  critical: "critical",
  high: "serious",
  medium: "warning",
  low: "neutral",
  // pipeline and events
  SUCCESS: "good",
  FAILED: "critical",
  RUNNING: "active",
  completed: "good",
  failed: "critical",
  running: "active",
  // proposals
  proposed: "active",
  validated: "good",
  approved: "good",
  applied: "good",
  verified: "good",
  superseded: "neutral",
  // trust
  trustworthy: "good",
  under_investigation: "serious",
  stale: "warning",
  untrusted: "critical",
};

export function Badge({ value, tone, children, title }) {
  const resolved = tone || STATUS_TONE[value] || "neutral";
  return (
    <span className={`badge tone-${resolved}`} title={title}>
      <span className="badge-glyph" aria-hidden="true">
        {TONE[resolved].glyph}
      </span>
      {children || titleCase(value)}
    </span>
  );
}

export function Card({ title, subtitle, actions, children, className = "" }) {
  return (
    <section className={`card ${className}`}>
      {(title || actions) && (
        <header className="card-head">
          <div>
            {title && <h2>{title}</h2>}
            {subtitle && <p className="muted">{subtitle}</p>}
          </div>
          {actions && <div className="card-actions">{actions}</div>}
        </header>
      )}
      {children}
    </section>
  );
}

export function Button({ children, onClick, busy, disabled, kind = "default", title }) {
  return (
    <button type="button" className={`button button-${kind}`} onClick={onClick} disabled={disabled || busy} title={title}>
      {busy ? "Working…" : children}
    </button>
  );
}

export function ErrorNote({ message, onDismiss }) {
  if (!message) return null;
  return (
    <div className="note note-error" role="alert">
      <span>{message}</span>
      {onDismiss && (
        <button type="button" className="link" onClick={onDismiss}>
          Dismiss
        </button>
      )}
    </div>
  );
}

export function Empty({ children }) {
  return <p className="empty">{children}</p>;
}

export function Json({ value }) {
  return <pre className="json">{typeof value === "string" ? value : JSON.stringify(value, null, 2)}</pre>;
}

export function KeyValue({ rows }) {
  return (
    <dl className="kv">
      {rows.map(([key, value]) => (
        <div key={key}>
          <dt>{key}</dt>
          <dd>{value}</dd>
        </div>
      ))}
    </dl>
  );
}

// Daily net revenue: what the source implies versus what analytics reports.
//
// Two series on one axis. Where the pipeline is correct the lines coincide, so
// days on which they differ get a marker: the gap is the story, and it must be
// findable without comparing two overlapping strokes.
import { useMemo, useRef, useState } from "react";
import { compactMoney, money, shortDate, signedMoney } from "../format.js";

const WIDTH = 760;
const HEIGHT = 250;
const MARGIN = { top: 16, right: 20, bottom: 30, left: 62 };
const SERIES = [
  { key: "source_net", label: "Source-derived (contract)", className: "series-1" },
  { key: "analytics_net", label: "Analytics daily_revenue", className: "series-2" },
];

function niceCeiling(value) {
  if (value <= 0) return 1;
  const magnitude = 10 ** Math.floor(Math.log10(value));
  const step = [1, 2, 2.5, 5, 10].find((m) => m * magnitude >= value);
  return step * magnitude;
}

export default function RevenueChart({ daily, currency, tolerance = 0.01 }) {
  const rows = useMemo(() => daily.filter((d) => d.currency === currency), [daily, currency]);
  const [hover, setHover] = useState(null);
  const [showTable, setShowTable] = useState(false);
  const frame = useRef(null);

  if (rows.length < 2) return <p className="empty">Not enough days of data to chart yet.</p>;

  const innerWidth = WIDTH - MARGIN.left - MARGIN.right;
  const innerHeight = HEIGHT - MARGIN.top - MARGIN.bottom;
  const top = niceCeiling(Math.max(...rows.flatMap((r) => [r.source_net, r.analytics_net])));
  const x = (index) => MARGIN.left + (index / (rows.length - 1)) * innerWidth;
  const y = (value) => MARGIN.top + innerHeight - (Math.max(value, 0) / top) * innerHeight;
  const path = (key) => rows.map((r, i) => `${i === 0 ? "M" : "L"}${x(i).toFixed(1)},${y(r[key]).toFixed(1)}`).join(" ");
  const ticks = [0, 0.25, 0.5, 0.75, 1].map((share) => share * top);
  const labelEvery = Math.ceil(rows.length / 7);
  const differs = (row) => Math.abs(row.analytics_net - row.source_net) > tolerance;
  const mismatched = rows.filter(differs).length;

  function onMove(event) {
    const box = frame.current.getBoundingClientRect();
    const position = ((event.clientX - box.left) / box.width) * WIDTH;
    const index = Math.round(((position - MARGIN.left) / innerWidth) * (rows.length - 1));
    setHover(Math.min(rows.length - 1, Math.max(0, index)));
  }

  const active = hover === null ? null : rows[hover];
  const tooltipLeft = hover === null ? 0 : (x(hover) / WIDTH) * 100;

  return (
    <div className="chart">
      <div className="chart-legend">
        {SERIES.map((series) => (
          <span key={series.key} className="legend-item">
            <span className={`legend-line ${series.className}`} aria-hidden="true" />
            {series.label}
          </span>
        ))}
        <span className="legend-item">
          <span className="legend-dot series-2" aria-hidden="true" />
          Day where they differ
        </span>
        <button type="button" className="link chart-toggle" onClick={() => setShowTable((v) => !v)}>
          {showTable ? "Show chart" : "Show as table"}
        </button>
      </div>

      {showTable ? (
        <div className="table-scroll">
          <table className="table numeric">
            <thead>
              <tr>
                <th>Day</th>
                <th>Source-derived</th>
                <th>Analytics</th>
                <th>Difference</th>
              </tr>
            </thead>
            <tbody>
              {[...rows].reverse().map((row) => (
                <tr key={row.date}>
                  <td>{shortDate(row.date)}</td>
                  <td>{money(row.source_net, currency)}</td>
                  <td>{money(row.analytics_net, currency)}</td>
                  <td>{differs(row) ? signedMoney(row.analytics_net - row.source_net, currency) : "matches"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ) : (
        <div className="chart-frame" ref={frame}>
          <svg
            viewBox={`0 0 ${WIDTH} ${HEIGHT}`}
            role="img"
            aria-label={`Daily net revenue in ${currency}, source-derived versus analytics. ${mismatched} of ${rows.length} days differ.`}
            onPointerMove={onMove}
            onPointerLeave={() => setHover(null)}
          >
            {ticks.map((tick) => (
              <g key={tick}>
                <line className="grid" x1={MARGIN.left} x2={WIDTH - MARGIN.right} y1={y(tick)} y2={y(tick)} />
                <text className="axis" x={MARGIN.left - 8} y={y(tick)} textAnchor="end" dominantBaseline="middle">
                  {compactMoney(tick, currency)}
                </text>
              </g>
            ))}
            {rows.map(
              (row, index) =>
                (index % labelEvery === 0 || index === rows.length - 1) && (
                  <text key={row.date} className="axis" x={x(index)} y={HEIGHT - 8} textAnchor="middle">
                    {shortDate(row.date)}
                  </text>
                ),
            )}
            {active && <line className="crosshair" x1={x(hover)} x2={x(hover)} y1={MARGIN.top} y2={MARGIN.top + innerHeight} />}
            {SERIES.map((series) => (
              <path key={series.key} className={`line ${series.className}`} d={path(series.key)} />
            ))}
            {rows.map(
              (row, index) =>
                differs(row) && (
                  <circle key={row.date} className="marker series-2" cx={x(index)} cy={y(row.analytics_net)} r="4.5" />
                ),
            )}
            {active &&
              SERIES.map((series) => (
                <circle key={series.key} className={`marker ${series.className}`} cx={x(hover)} cy={y(active[series.key])} r="4.5" />
              ))}
          </svg>
          {active && (
            <div className={`tooltip ${tooltipLeft > 60 ? "tooltip-left" : ""}`} style={{ left: `${tooltipLeft}%` }}>
              <div className="tooltip-title">{shortDate(active.date)}</div>
              {SERIES.map((series) => (
                <div key={series.key} className="tooltip-row">
                  <span className={`legend-line ${series.className}`} aria-hidden="true" />
                  <strong>{money(active[series.key], currency)}</strong>
                  <span className="muted">{series.label}</span>
                </div>
              ))}
              <div className="tooltip-row tooltip-delta">
                {differs(active)
                  ? `Analytics is ${signedMoney(active.analytics_net - active.source_net, currency)} against the source`
                  : "Analytics matches the source"}
              </div>
            </div>
          )}
        </div>
      )}
      <p className="muted chart-note">
        {mismatched === 0
          ? "The two lines coincide on every day shown: analytics matches the source."
          : `${mismatched} of ${rows.length} days differ. The lines coincide wherever analytics matches the source.`}
      </p>
    </div>
  );
}

// Overview: is the data trustworthy right now, and what is the pipeline doing?
import { useState } from "react";
import { usePoll } from "../api.js";
import { ago, clock, money, number, signedMoney, titleCase } from "../format.js";
import { Badge, Card, Empty } from "./common.jsx";
import RevenueChart from "./RevenueChart.jsx";

function RevenueTile({ currency, sides }) {
  const matches = sides.within_tolerance;
  return (
    <div className="tile">
      <div className="tile-label">Net revenue · {currency}</div>
      <div className="tile-value">{money(sides.analytics.net, currency)}</div>
      <div className="tile-foot">
        <Badge tone={matches ? "good" : "critical"}>
          {matches ? "Matches source" : `${signedMoney(sides.net_difference, currency)} vs source`}
        </Badge>
        <span className="muted">Source-derived {money(sides.source.net, currency)}</span>
      </div>
      <dl className="tile-breakdown">
        <div>
          <dt>Gross paid</dt>
          <dd>{money(sides.analytics.gross, currency)}</dd>
          <dd className="muted">source {money(sides.source.gross, currency)}</dd>
        </div>
        <div>
          <dt>Refunds subtracted</dt>
          <dd>{money(sides.analytics.refunds, currency)}</dd>
          <dd className="muted">source {money(sides.source.refunds, currency)}</dd>
        </div>
      </dl>
    </div>
  );
}

function PipelineTile({ pipeline, orderCounts }) {
  const run = pipeline.last_run;
  const orders = Object.values(orderCounts).reduce(
    (sum, c) => ({ source: sum.source + c.source, analytics: sum.analytics + c.analytics }),
    { source: 0, analytics: 0 },
  );
  return (
    <div className="tile">
      <div className="tile-label">Pipeline · order_revenue</div>
      <div className="tile-value tile-value-small">
        {run ? <Badge value={run.status}>{`Run ${run.run_id} ${run.status}`}</Badge> : "No runs yet"}
      </div>
      <div className="tile-foot">
        <Badge tone={pipeline.fresh ? "good" : "warning"}>
          {pipeline.fresh ? "Fresh" : "Stale"} · refreshed {ago(pipeline.freshness_seconds)}
        </Badge>
      </div>
      {run?.error_summary && <p className="tile-error">{run.error_summary}</p>}
      <dl className="tile-breakdown">
        <div>
          <dt>Orders</dt>
          <dd>{number(orders.analytics)} in analytics</dd>
          <dd className="muted">{number(orders.source)} in source</dd>
        </div>
        <div>
          <dt>Transformation</dt>
          <dd>{pipeline.transform ? `Version ${pipeline.transform.version}` : "–"}</dd>
          <dd className="muted">{pipeline.transform?.author}</dd>
        </div>
      </dl>
    </div>
  );
}

function LiveFeed() {
  const { data } = usePoll("/transactions/live?limit=14", 2000);
  if (!data) return <Empty>Loading…</Empty>;
  return (
    <>
      <p className="muted feed-totals">
        {number(data.totals.orders)} orders · {number(data.totals.payments)} payments · {number(data.totals.refunds)} refunds in the source
      </p>
      <table className="table">
        <tbody>
          {data.events.map((event) => (
            <tr key={`${event.kind}-${event.id}`}>
              <td className="muted nowrap">{clock(event.at)}</td>
              <td>
                {titleCase(event.kind)} #{event.id}
                {event.kind !== "order" && <span className="muted"> · order #{event.order_id}</span>}
              </td>
              <td>
                <span className="status-text">{event.status}</span>
              </td>
              <td className="right nowrap">{money(event.amount, event.currency)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </>
  );
}

function RunHistory() {
  const { data } = usePoll("/pipeline/runs?limit=8", 3000);
  if (!data) return <Empty>Loading…</Empty>;
  if (data.length === 0) return <Empty>No pipeline runs yet.</Empty>;
  return (
    <table className="table">
      <thead>
        <tr>
          <th>Run</th>
          <th>Status</th>
          <th>Trigger</th>
          <th className="right">Loaded</th>
          <th>Quality checks</th>
        </tr>
      </thead>
      <tbody>
        {data.map((run) => {
          const failed = run.checks.filter((c) => !c.passed);
          return (
            <tr key={run.run_id}>
              <td className="nowrap">
                #{run.run_id} <span className="muted">{clock(run.started_at)}</span>
              </td>
              <td>
                <Badge value={run.status} />
              </td>
              <td className="muted">{titleCase(run.trigger)}</td>
              <td className="right">{number(run.loaded_count)}</td>
              <td>
                {failed.length === 0 ? (
                  <span className="muted">{run.checks.length} passed</span>
                ) : (
                  <span title={failed.map((c) => c.check_name).join("\n")}>
                    <Badge tone="critical">{failed.length} failed</Badge>{" "}
                    <span className="muted">{failed[0].check_name}{failed.length > 1 ? ` +${failed.length - 1}` : ""}</span>
                  </span>
                )}
              </td>
            </tr>
          );
        })}
      </tbody>
    </table>
  );
}

export default function Overview({ metrics, onOpenIncident }) {
  const currencies = metrics ? Object.keys(metrics.reconciliation.by_currency) : [];
  const [currency, setCurrency] = useState("INR");
  if (!metrics) return <Empty>Loading the dashboard…</Empty>;
  const selected = currencies.includes(currency) ? currency : currencies[0];
  const incident = metrics.active_incident;

  return (
    <div className="stack">
      {incident && (
        <div className="banner" role="status">
          <div>
            <Badge value={incident.severity} /> <strong>{incident.incident_id}</strong>{" "}
            <Badge value={incident.status} />
            <p>{incident.summary}</p>
          </div>
          <button type="button" className="button button-primary" onClick={() => onOpenIncident(incident.incident_id)}>
            Open incident
          </button>
        </div>
      )}

      <div className="tiles">
        {currencies.map((code) => (
          <RevenueTile key={code} currency={code} sides={metrics.reconciliation.by_currency[code]} />
        ))}
        <PipelineTile pipeline={metrics.pipeline} orderCounts={metrics.order_counts} />
      </div>

      <Card
        title="Daily net revenue: source versus analytics"
        subtitle="Source-derived revenue is computed from the operational tables by the approved net_revenue contract."
        actions={
          currencies.length > 1 && (
            <label className="field-inline">
              Currency
              <select value={selected} onChange={(event) => setCurrency(event.target.value)}>
                {currencies.map((code) => (
                  <option key={code}>{code}</option>
                ))}
              </select>
            </label>
          )
        }
      >
        <RevenueChart daily={metrics.daily} currency={selected} tolerance={metrics.reconciliation.tolerance} />
      </Card>

      <div className="columns">
        <Card title="Live source transactions">
          <LiveFeed />
        </Card>
        <Card title="Recent pipeline runs">
          <RunHistory />
        </Card>
      </div>
    </div>
  );
}

// Scenario Lab: inject one known fault, or reset to the clean baseline.
import { api, useAction, usePoll } from "../api.js";
import { dateTime, money, signedMoney } from "../format.js";
import { Badge, Button, Card, Empty, ErrorNote } from "./common.jsx";

function MetricsTable({ baseline, after }) {
  const currencies = Object.keys(baseline.by_currency);
  return (
    <table className="table numeric">
      <thead>
        <tr>
          <th>Currency</th>
          <th>Source-derived net</th>
          <th>Analytics net before</th>
          <th>Analytics net after</th>
          <th>Analytics vs source</th>
        </tr>
      </thead>
      <tbody>
        {currencies.map((currency) => {
          const before = baseline.by_currency[currency];
          const now = after?.by_currency[currency];
          return (
            <tr key={currency}>
              <td>{currency}</td>
              <td>{money((now || before).source.net, currency)}</td>
              <td>{money(before.analytics.net, currency)}</td>
              <td>{now ? money(now.analytics.net, currency) : "–"}</td>
              <td>
                {!now ? "–" : now.within_tolerance ? "matches" : signedMoney(now.net_difference, currency)}
              </td>
            </tr>
          );
        })}
      </tbody>
    </table>
  );
}

export default function ScenarioLab({ onChanged, onOpenIncident, activeIncident }) {
  const { data, refresh } = usePoll("/scenarios", 4000);
  const action = useAction();
  if (!data) return <Empty>Loading scenarios…</Empty>;
  const active = data.active?.scenario_id;

  async function inject(scenarioId) {
    const report = await action.run(() => api(`/scenarios/${scenarioId}/inject`, { method: "POST" }));
    await refresh();
    onChanged();
    if (report?.incident_id) onOpenIncident(report.incident_id);
  }

  return (
    <div className="stack">
      <Card
        title="Scenario lab"
        subtitle="Each scenario introduces one deterministic fault into the demo environment. DataTraceMind is not told which one: it has to find the cause from the same evidence an engineer would have."
      >
        <ErrorNote message={action.error} onDismiss={action.clearError} />
        <div className="scenarios">
          {data.scenarios.map((scenario) => (
            <article key={scenario.scenario_id} className={`scenario ${active === scenario.scenario_id ? "scenario-active" : ""}`}>
              <header>
                <span className="scenario-id">{scenario.scenario_id}</span>
                <span className="muted">{scenario.failure_type}</span>
              </header>
              <h3>{scenario.name}</h3>
              <p>{scenario.description}</p>
              {active === scenario.scenario_id ? (
                <Badge tone="serious">Injected {dateTime(data.active.injected_at)}</Badge>
              ) : (
                <Button
                  onClick={() => inject(scenario.scenario_id)}
                  busy={action.busy}
                  disabled={Boolean(active)}
                  title={active ? "Reset the demo before injecting another scenario" : undefined}
                >
                  Inject fault
                </Button>
              )}
            </article>
          ))}
        </div>
        {active && (
          <p className="muted">
            {active} is injected. Reset the demo (top right) to return to the clean baseline before injecting another scenario.
            {activeIncident && (
              <>
                {" "}
                <button type="button" className="link" onClick={() => onOpenIncident(activeIncident.incident_id)}>
                  Open {activeIncident.incident_id}
                </button>
              </>
            )}
          </p>
        )}
      </Card>

      {data.active?.baseline_metrics && (
        <Card title="Baseline versus post-injection" subtitle="Net revenue per currency, before the fault and after the first pipeline run with it.">
          <MetricsTable baseline={data.active.baseline_metrics} after={data.active.post_injection_metrics} />
        </Card>
      )}
    </div>
  );
}

// Repair review: the diff, why it is believed correct, the staging proof, and
// the human decision. The server enforces every rule; this page only shows them.
import { useState } from "react";
import { api, useAction } from "../api.js";
import { dateTime, money, signedMoney } from "../format.js";
import { Badge, Button, Card, ErrorNote, KeyValue } from "./common.jsx";

const STAGES = ["proposed", "validated", "approved", "applied", "verified"];
const REACHED = {
  proposed: 1,
  validation_failed: 1,
  validated: 2,
  rejected: 2,
  approved: 3,
  applied: 4,
  application_failed: 4,
  verified: 5,
  superseded: 0,
};

function Diff({ text }) {
  return (
    <pre className="diff" aria-label="Patch diff">
      {text.split("\n").map((line, index) => {
        const kind = line.startsWith("+++") || line.startsWith("---") ? "file" : line.startsWith("+") ? "add" : line.startsWith("-") ? "del" : line.startsWith("@@") ? "hunk" : "ctx";
        return (
          <span key={index} className={`diff-${kind}`}>
            {line || " "}
            {"\n"}
          </span>
        );
      })}
    </pre>
  );
}

function BeforeAfter({ data }) {
  if (!data?.before) return null;
  const currencies = Object.keys(data.before.by_currency);
  const cell = (side, currency) =>
    side.by_currency[currency].within_tolerance ? (
      <Badge tone="good">matches source</Badge>
    ) : (
      <Badge tone="critical">{signedMoney(side.by_currency[currency].net_difference, currency)}</Badge>
    );
  return (
    <table className="table numeric">
      <thead>
        <tr>
          <th>Currency</th>
          <th>Source-derived net</th>
          <th>Analytics now</th>
          <th>Staging with patch</th>
          <th>Now vs source</th>
          <th>Staging vs source</th>
        </tr>
      </thead>
      <tbody>
        {currencies.map((currency) => (
          <tr key={currency}>
            <td>{currency}</td>
            <td>{money(data.before.by_currency[currency].source.net, currency)}</td>
            <td>{money(data.before.by_currency[currency].analytics.net, currency)}</td>
            <td>{money(data.after.by_currency[currency].analytics.net, currency)}</td>
            <td>{cell(data.before, currency)}</td>
            <td>{cell(data.after, currency)}</td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

function Decision({ incident, proposal, onChanged }) {
  const [approver, setApprover] = useState("");
  const [reason, setReason] = useState("");
  const action = useAction();
  const body = { patch_hash: proposal.patch_hash, approver: approver.trim() };
  const decide = (path, extra = {}) =>
    action.run(async () => {
      await api(`/incidents/${incident.incident_id}/${path}`, { method: "POST", body: { ...body, ...extra } });
      await onChanged();
    });

  return (
    <div className="decision">
      <h3>Your decision</h3>
      <p>
        Approving applies <strong>exactly this patch</strong> (hash <code>{proposal.patch_hash.slice(0, 12)}</code>) to the demo
        environment, reruns the pipeline, and verifies recovery. Nothing is applied without it.
      </p>
      <ErrorNote message={action.error} onDismiss={action.clearError} />
      <div className="decision-fields">
        <label>
          Your name
          <input value={approver} onChange={(event) => setApprover(event.target.value)} placeholder="Name recorded in the audit log" maxLength={60} />
        </label>
        <label>
          Reason, if rejecting
          <input value={reason} onChange={(event) => setReason(event.target.value)} placeholder="Optional" maxLength={500} />
        </label>
      </div>
      <div className="decision-actions">
        <Button kind="primary" busy={action.busy} disabled={!approver.trim()} onClick={() => decide("approve")}>
          Approve and apply
        </Button>
        <Button kind="danger" busy={action.busy} disabled={!approver.trim()} onClick={() => decide("reject", { reason: reason.trim() || null })}>
          Reject
        </Button>
      </div>
    </div>
  );
}

export default function RepairReview({ incident, onChanged }) {
  const proposal = incident.proposal;
  if (!proposal) return null;
  const validation = proposal.validation_result;
  const postFix = proposal.post_fix_result;
  const reached = REACHED[proposal.status] ?? 0;
  const approval = incident.approvals.findLast((a) => a.proposal_id === proposal.proposal_id);
  const failedChecks = validation?.checks.filter((c) => !c.passed) || [];

  return (
    <Card
      title={`Repair review · ${proposal.proposal_id}`}
      subtitle={`Patch ${proposal.patch_hash.slice(0, 12)} against transformation version ${proposal.base_version} · proposed ${dateTime(proposal.created_at)}`}
      actions={<Badge value={proposal.status} />}
    >
      <ol className="stages" aria-label="Repair status">
        {STAGES.map((stage, index) => (
          <li key={stage} className={index < reached ? "stage-done" : ""}>
            <span aria-hidden="true">{index < reached ? "✓" : index + 1}</span> {stage}
          </li>
        ))}
      </ol>

      <h3>Patch · {proposal.target_file}</h3>
      <Diff text={proposal.diff} />

      <KeyValue
        rows={[
          ["Why this fixes the root cause", proposal.rationale],
          ["Risk", proposal.risk],
          ["Rollback", proposal.rollback_plan],
          ["Evidence relied on", (proposal.cited_evidence.evidence || []).join(", ") || "–"],
        ]}
      />

      {validation && (
        <>
          <h3>
            Staging validation <Badge tone={validation.passed ? "good" : "critical"}>{validation.passed ? "Passed" : "Failed"}</Badge>
          </h3>
          <p className="muted">
            Deterministic: the patched transformation was run against a staging copy
            {validation.staging_run_id ? ` (staging run ${validation.staging_run_id}, ${validation.staging_status})` : ""}. No model decides the result.
          </p>
          {validation.failures.length > 0 && (
            <ul className="failures">
              {validation.failures.map((failure) => (
                <li key={failure}>{failure}</li>
              ))}
            </ul>
          )}
          <BeforeAfter data={validation.before_after} />
          <div className="columns">
            <div>
              <h4>
                Regression cases · {validation.regression.filter((c) => c.passed).length} of {validation.regression.length} pass
              </h4>
              <ul className="checklist">
                {validation.regression.map((item) => (
                  <li key={item.name} title={JSON.stringify({ expected: item.expected, actual: item.actual }, null, 1)}>
                    <Badge tone={item.passed ? "good" : "critical"}>{item.passed ? "Pass" : "Fail"}</Badge> {item.name}
                  </li>
                ))}
              </ul>
            </div>
            <div>
              <h4>
                Quality checks in staging · {validation.checks.length - failedChecks.length} of {validation.checks.length} pass
              </h4>
              <ul className="checklist">
                {validation.checks.map((check) => (
                  <li key={check.check_name} title={check.expected_condition}>
                    <Badge tone={check.passed ? "good" : "critical"}>{check.passed ? "Pass" : "Fail"}</Badge> {check.check_name}
                  </li>
                ))}
              </ul>
            </div>
          </div>
        </>
      )}

      {approval && (
        <p className="note">
          <Badge value={approval.decision} tone={approval.decision === "approved" ? "good" : "neutral"} /> by{" "}
          <strong>{approval.actor}</strong> on {dateTime(approval.decided_at)} for patch <code>{approval.patch_hash.slice(0, 12)}</code>
          {approval.reason ? ` — “${approval.reason}”` : ""}
        </p>
      )}

      {postFix && (
        <>
          <h3>
            Post-fix verification <Badge tone={postFix.passed ? "good" : "critical"}>{postFix.passed ? "Recovered" : "Failed"}</Badge>
          </h3>
          <p>
            Pipeline run {postFix.etl_run_id} finished {postFix.etl_status} on transformation version {postFix.transform_version}.{" "}
            {postFix.passed
              ? `All ${postFix.checks.length} quality checks pass.`
              : `Failed checks: ${postFix.failed_checks.join(", ") || postFix.etl_error}. The previous transformation was redeployed (version ${postFix.rolled_back_to_version}).`}
          </p>
        </>
      )}

      {incident.status === "awaiting_approval" && proposal.status === "validated" && (
        <Decision incident={incident} proposal={proposal} onChanged={onChanged} />
      )}
    </Card>
  );
}

// Incident page: anomaly -> evidence -> root cause -> patch -> staging proof ->
// human approval -> verified recovery, top to bottom.
import { useState } from "react";
import { api, useAction, usePoll } from "../api.js";
import { clock, dateTime, money, number, titleCase } from "../format.js";
import { Badge, Button, Card, Empty, ErrorNote, Json } from "./common.jsx";
import RepairReview from "./RepairReview.jsx";

const LIFECYCLE = [
  ["detected", "Detected"],
  ["investigating", "Investigating"],
  ["diagnosed", "Diagnosed"],
  ["repair_proposed", "Repair proposed"],
  ["validating", "Validating"],
  ["awaiting_approval", "Awaiting approval"],
  ["applying", "Applying"],
  ["verifying", "Verifying"],
  ["resolved", "Resolved"],
];
const RESTARTABLE = new Set([
  "detected", "diagnosed", "repair_proposed", "validation_failed", "awaiting_approval", "application_failed",
  "rejected", "escalated",
]);
const OFF_PATH = new Set(["validation_failed", "application_failed", "rejected", "escalated"]);

function Lifecycle({ incident }) {
  const visited = new Set(incident.events.filter((e) => e.event_type === "lifecycle").map((e) => e.status));
  return (
    <ol className="lifecycle" aria-label="Incident lifecycle">
      {LIFECYCLE.map(([status, label]) => {
        const state = incident.status === status ? "current" : visited.has(status) ? "done" : "todo";
        return (
          <li key={status} className={`step step-${state}`} aria-current={state === "current" ? "step" : undefined}>
            <span className="step-dot" aria-hidden="true">
              {state === "done" ? "✓" : ""}
            </span>
            {label}
          </li>
        );
      })}
    </ol>
  );
}

function Trigger({ incident }) {
  const currencies = Object.keys(incident.source_metrics || {});
  return (
    <Card title="What the monitor found" subtitle={`Deterministic checks after ETL run ${incident.trigger.etl_run_id ?? "–"} (${incident.trigger.etl_status ?? "freshness monitor"}). No model decides that something is wrong.`}>
      {currencies.length > 0 && (
        <table className="table numeric">
          <thead>
            <tr>
              <th>Currency</th>
              <th>Source gross</th>
              <th>Source refunds</th>
              <th>Source net</th>
              <th>Analytics gross</th>
              <th>Analytics refunds</th>
              <th>Analytics net</th>
            </tr>
          </thead>
          <tbody>
            {currencies.map((currency) => {
              const source = incident.source_metrics[currency];
              const target = incident.target_metrics[currency];
              return (
                <tr key={currency}>
                  <td>{currency}</td>
                  <td>{money(source.gross, currency)}</td>
                  <td>{money(source.refunds, currency)}</td>
                  <td>{money(source.net, currency)}</td>
                  <td>{money(target.gross, currency)}</td>
                  <td>{money(target.refunds, currency)}</td>
                  <td>{money(target.net, currency)}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      )}
      <ul className="checks">
        {incident.trigger.failed_checks.map((check) => (
          <li key={check.check_name}>
            <details>
              <summary>
                <Badge value={check.severity}>{`Failed · ${check.severity}`}</Badge> <code>{check.check_name}</code>
                <span className="muted"> — expected: {check.expected_condition}</span>
              </summary>
              <Json value={check.observed_value} />
            </details>
          </li>
        ))}
      </ul>
    </Card>
  );
}

function Timeline({ events }) {
  return (
    <ol className="timeline">
      {events.map((event) => (
        <li key={event.event_id} className={`event event-${event.event_type}`}>
          <span className="event-time">{clock(event.created_at)}</span>
          <span className="event-agent">{titleCase(event.agent.replace(/^human:/, "human · "))}</span>
          <span className="event-body">
            <Badge value={event.status} />{" "}
            {event.event_type === "tool_call" && <span className="tag">tool</span>}
            {event.payload?.evidence_id && <span className="tag">{event.payload.evidence_id}</span>} {event.summary}
            {event.payload?.input_tokens !== undefined && (
              <span className="muted">
                {" "}
                · {number(event.payload.input_tokens)} in / {number(event.payload.output_tokens)} out tokens · est. $
                {event.payload.est_cost_usd}
              </span>
            )}
          </span>
        </li>
      ))}
    </ol>
  );
}

function Evidence({ evidence, cited }) {
  if (evidence.length === 0) return <Empty>No evidence collected yet.</Empty>;
  return (
    <ul className="evidence">
      {evidence.map((item) => (
        <li key={item.evidence_id} id={item.evidence_id} className={cited.has(item.evidence_id) ? "evidence-cited" : ""}>
          <details>
            <summary>
              <span className="tag tag-strong">{item.evidence_id}</span> {item.description}
              <span className="muted">
                {" "}
                · {item.query_or_tool} · {item.source} · by {titleCase(item.collected_by)}
              </span>
              {cited.has(item.evidence_id) && <span className="tag">cited in root cause</span>}
            </summary>
            {Object.keys(item.arguments).length > 0 && (
              <p className="muted">
                Arguments: <code>{JSON.stringify(item.arguments)}</code>
              </p>
            )}
            <Json value={item.result_summary?.content ?? item.result_summary?.text ?? item.result_summary} />
          </details>
        </li>
      ))}
    </ul>
  );
}

function Hypotheses({ state }) {
  const hypotheses = state.hypotheses || [];
  if (hypotheses.length === 0) return null;
  const selected = state.selected_root_cause;
  return (
    <Card
      title="Root cause"
      subtitle="Competing hypotheses ranked by the analyst. A cause counts as confirmed only when it cites evidence that exists and clears the confidence bar."
      actions={selected ? <Badge tone="good">Confirmed</Badge> : <Badge tone="warning">Not confirmed</Badge>}
    >
      {selected && (
        <div className="root-cause">
          <p>{selected.summary}</p>
          <p className="muted">
            Implicated: <code>{selected.implicated_component}</code>
          </p>
        </div>
      )}
      {state.analysis?.business_rule_ambiguity && (
        <p className="note note-error">Needs a human decision: {state.analysis.business_rule_ambiguity}</p>
      )}
      <ol className="hypotheses">
        {hypotheses.map((h) => (
          <li key={h.hypothesis_id} className={selected?.hypothesis_id === h.hypothesis_id ? "hypothesis-selected" : ""}>
            <div className="hypothesis-head">
              <span className="tag tag-strong">{h.hypothesis_id}</span>
              <span className="tag">{titleCase(h.category)}</span>
              <span className="meter" role="img" aria-label={`Confidence ${Math.round(h.confidence * 100)} percent`}>
                <span style={{ width: `${Math.round(h.confidence * 100)}%` }} />
              </span>
              <span className="muted">{Math.round(h.confidence * 100)}% confidence</span>
            </div>
            <p>{h.statement}</p>
            <p className="muted">{h.reasoning}</p>
            <p className="evidence-links">
              {h.supporting_evidence.length > 0 && <span className="muted">Supported by </span>}
              {h.supporting_evidence.map((id) => (
                <a key={id} className="tag" href={`#${id}`} onClick={(e) => { e.preventDefault(); document.getElementById(id)?.scrollIntoView({ behavior: "smooth", block: "center" }); }}>
                  {id}
                </a>
              ))}
              {h.contradicting_evidence.length > 0 && <span className="muted"> Contradicted by </span>}
              {h.contradicting_evidence.map((id) => (
                <span key={id} className="tag">
                  {id}
                </span>
              ))}
            </p>
          </li>
        ))}
      </ol>
    </Card>
  );
}

function Runs({ runs }) {
  if (runs.length === 0) return null;
  return (
    <Card title="Investigation runs" subtitle="One row per run; each is one neatlogs trace. Cost is an estimate at API list prices (the model runs on a flat-rate plan).">
      <div className="table-scroll">
        <table className="table numeric">
          <thead>
            <tr>
              <th>Run</th>
              <th>Outcome</th>
              <th>Workflow</th>
              <th>Model</th>
              <th>Duration</th>
              <th>Role turns</th>
              <th>Tool calls</th>
              <th>Failed / retries</th>
              <th>Input tokens</th>
              <th>Output tokens</th>
              <th>Est. cost</th>
              <th>Trace ID</th>
            </tr>
          </thead>
          <tbody>
            {runs.map((run) => (
              <tr key={run.run_id}>
                <td>#{run.run_id}</td>
                <td>
                  <Badge value={run.status} />
                </td>
                <td>{run.workflow_version}</td>
                <td>{run.model}</td>
                <td>{run.duration_s ? `${Number(run.duration_s).toFixed(0)}s` : "–"}</td>
                <td>{run.role_turns}</td>
                <td>{run.tool_calls}</td>
                <td>
                  {run.failed_tool_calls} / {run.retries}
                </td>
                <td title={`${number(run.cached_input_tokens)} cached`}>{number(run.input_tokens)}</td>
                <td>{number(run.output_tokens)}</td>
                <td>${Number(run.est_cost_usd).toFixed(3)}</td>
                <td>
                  <code>{run.trace_id ? `${run.trace_id.slice(0, 12)}…` : "not traced"}</code>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </Card>
  );
}

function IncidentDetail({ incidentId, agent, onChanged }) {
  const { data: incident, error, refresh } = usePoll(`/incidents/${incidentId}`, 2000);
  const action = useAction();
  const [showTools, setShowTools] = useState(true);
  if (error && !incident) return <ErrorNote message={error.message} />;
  if (!incident) return <Empty>Loading {incidentId}…</Empty>;

  const changed = async () => {
    await refresh();
    onChanged();
  };
  const investigate = () =>
    action.run(async () => {
      await api(`/incidents/${incidentId}/investigate`, { method: "POST" });
      await changed();
    });
  const cited = new Set(incident.state.selected_root_cause?.supporting_evidence || []);
  const events = showTools ? incident.events : incident.events.filter((e) => e.event_type !== "tool_call");
  const escalation = incident.state.errors?.at(-1);
  const canInvestigate = RESTARTABLE.has(incident.status);

  return (
    <div className="stack">
      <Card>
        <div className="incident-head">
          <div>
            <h1>
              {incident.incident_id} <Badge value={incident.severity} /> <Badge value={incident.status} />
            </h1>
            <p className="incident-summary">{incident.summary}</p>
            <p className="muted">
              {titleCase(incident.incident_type)} · detected {dateTime(incident.detected_at)}
              {incident.resolved_at ? ` · resolved ${dateTime(incident.resolved_at)}` : ""}
            </p>
          </div>
          {canInvestigate && (
            <div className="incident-actions">
              <Button
                kind="primary"
                onClick={investigate}
                busy={action.busy}
                disabled={!agent?.available || agent?.investigation_running}
                title={agent?.available ? undefined : agent?.detail}
              >
                {incident.status === "detected" ? "Investigate" : "Investigate again"}
              </Button>
              {!agent?.available && <p className="muted">Agent unavailable. {agent?.detail}</p>}
            </div>
          )}
        </div>
        <ErrorNote message={action.error} onDismiss={action.clearError} />
        <Lifecycle incident={incident} />
        {OFF_PATH.has(incident.status) && (
          <p className="note note-error">
            <strong>{titleCase(incident.status)}.</strong>{" "}
            {incident.status === "escalated" && escalation
              ? `A human needs to take this: ${escalation.reason}`
              : incident.events.at(-1)?.summary}
          </p>
        )}
      </Card>

      <Trigger incident={incident} />
      <Hypotheses state={incident.state} />
      <RepairReview incident={incident} onChanged={changed} />

      <Card
        title="Agent workflow"
        subtitle="Every step the supervisor and the agent roles took, in order."
        actions={
          <label className="field-inline">
            <input type="checkbox" checked={showTools} onChange={(event) => setShowTools(event.target.checked)} /> Show tool calls
          </label>
        }
      >
        <Timeline events={events} />
      </Card>

      <Card title={`Evidence · ${incident.evidence.length} items`} subtitle="Each item is the recorded result of a tool call, a contract, or code as deployed. Open one to see exactly what was returned.">
        <Evidence evidence={incident.evidence} cited={cited} />
      </Card>

      <Runs runs={incident.investigation_runs} />
    </div>
  );
}

export default function Incidents({ selectedId, onSelect, agent, onChanged }) {
  const { data: incidents } = usePoll("/incidents", 3000);
  if (!incidents) return <Empty>Loading incidents…</Empty>;
  if (incidents.length === 0)
    return (
      <Card title="Incidents">
        <Empty>No incidents. The pipeline is healthy; inject a fault from the Scenario Lab to see one.</Empty>
      </Card>
    );
  const current = selectedId && incidents.some((i) => i.incident_id === selectedId) ? selectedId : incidents[0].incident_id;
  return (
    <div className="stack">
      {incidents.length > 1 && (
        <nav className="incident-tabs" aria-label="Incidents">
          {incidents.map((incident) => (
            <button
              key={incident.incident_id}
              type="button"
              className={incident.incident_id === current ? "active" : ""}
              onClick={() => onSelect(incident.incident_id)}
            >
              {incident.incident_id} <Badge value={incident.status} />
            </button>
          ))}
        </nav>
      )}
      <IncidentDetail key={current} incidentId={current} agent={agent} onChanged={onChanged} />
    </div>
  );
}

// Audit timeline: who did what, to what, and with what result.
import { usePoll } from "../api.js";
import { dateTime, titleCase } from "../format.js";
import { Badge, Card, Empty } from "./common.jsx";

export default function Audit() {
  const { data } = usePoll("/audit?limit=300", 4000);
  if (!data) return <Empty>Loading the audit log…</Empty>;
  return (
    <Card
      title="Audit log"
      subtitle="Detection, lifecycle changes, patch proposals, validation, human decisions, application, and verification. Newest first."
    >
      {data.length === 0 ? (
        <Empty>Nothing recorded yet.</Empty>
      ) : (
        <div className="table-scroll">
          <table className="table">
            <thead>
              <tr>
                <th>Time</th>
                <th>Actor</th>
                <th>Action</th>
                <th>Target</th>
                <th>Result</th>
                <th>Details</th>
              </tr>
            </thead>
            <tbody>
              {data.map((entry) => (
                <tr key={entry.audit_id}>
                  <td className="nowrap muted">{dateTime(entry.created_at)}</td>
                  <td className="nowrap">{titleCase(entry.actor.replace(/^human:/, "human · "))}</td>
                  <td>
                    <code>{entry.action}</code>
                  </td>
                  <td className="nowrap">{entry.target}</td>
                  <td>
                    <Badge value={entry.result} />
                  </td>
                  <td className="audit-details">
                    {Object.entries(entry.details)
                      .filter(([key]) => key !== "incident_id")
                      .map(([key, value]) => (
                        <span key={key}>
                          <span className="muted">{titleCase(key)}:</span>{" "}
                          {typeof value === "string" && /^[0-9a-f]{64}$/.test(value) ? <code>{value.slice(0, 12)}</code> : typeof value === "object" ? JSON.stringify(value) : String(value)}
                        </span>
                      ))}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </Card>
  );
}

import { useEffect, useState } from "react";
import { api, getAccessCode, setAccessCode, useAction, usePoll } from "./api.js";
import { titleCase } from "./format.js";
import Audit from "./components/Audit.jsx";
import { Badge, Button, ErrorNote } from "./components/common.jsx";
import Incidents from "./components/Incident.jsx";
import Overview from "./components/Overview.jsx";
import ScenarioLab from "./components/ScenarioLab.jsx";

const TABS = [
  ["overview", "Overview"],
  ["lab", "Scenario lab"],
  ["incidents", "Incidents"],
  ["audit", "Audit log"],
];
const TRUST_TEXT = {
  trustworthy: "Data is trustworthy",
  under_investigation: "Under investigation",
  stale: "Data is stale",
  untrusted: "Data does not reconcile",
};

// The view lives in the URL hash (#/incidents/INC-0001) so a reload or a
// shared link lands on the same page.
function readRoute() {
  const [tab, id] = window.location.hash.replace(/^#\/?/, "").split("/");
  return { tab: TABS.some(([key]) => key === tab) ? tab : "overview", id: id || null };
}

export default function App() {
  const [route, setRoute] = useState(readRoute);
  const [code, setCode] = useState(getAccessCode);
  const metrics = usePoll("/metrics/summary", 2500);
  const agent = usePoll("/agent/status", 5000);
  const health = usePoll("/health", 4000);
  const action = useAction();

  useEffect(() => {
    const onHash = () => setRoute(readRoute());
    window.addEventListener("hashchange", onHash);
    return () => window.removeEventListener("hashchange", onHash);
  }, []);

  const go = (tab, id) => {
    window.location.hash = id ? `/${tab}/${id}` : `/${tab}`;
  };
  const refreshAll = () => {
    metrics.refresh();
    agent.refresh();
    health.refresh();
  };
  const post = (path) =>
    action.run(async () => {
      await api(path, { method: "POST" });
      refreshAll();
    });
  const reset = async () => {
    if (!window.confirm("Reset the demo? This restores the clean baseline and clears all incidents.")) return;
    await post("/demo/reset");
    go("overview");
  };

  const trafficRunning = health.data?.traffic_running;
  const activeIncident = metrics.data?.active_incident;
  const trust = metrics.data?.trust;

  return (
    <div className="app">
      <header className="topbar">
        <div className="brand">
          <span className="brand-mark" aria-hidden="true" />
          <div>
            <div className="brand-name">DataTraceMind</div>
            <div className="brand-tag">Agentic data reliability engineer</div>
          </div>
        </div>
        <div className="topbar-status">
          {trust && <Badge value={trust}>{TRUST_TEXT[trust]}</Badge>}
          {agent.data && (
            <Badge tone={agent.data.available ? (agent.data.investigation_running ? "active" : "good") : "warning"} title={agent.data.detail}>
              {agent.data.available
                ? agent.data.investigation_running
                  ? "Agent investigating"
                  : `Agent available · ${agent.data.model}`
                : "Agent unavailable"}
            </Badge>
          )}
        </div>
        <div className="topbar-actions">
          {agent.data?.access_code_required && (
            <input
              className="access-code"
              type="password"
              placeholder="Demo access code"
              aria-label="Demo access code"
              value={code}
              onChange={(event) => {
                setCode(event.target.value);
                setAccessCode(event.target.value);
              }}
            />
          )}
          <Button onClick={() => post(trafficRunning ? "/demo/traffic/stop" : "/demo/traffic/start")} busy={action.busy}>
            {trafficRunning ? "Stop traffic" : "Start traffic"}
          </Button>
          <Button onClick={reset} busy={action.busy} kind="danger">
            Reset demo
          </Button>
        </div>
      </header>

      <nav className="tabs" aria-label="Sections">
        {TABS.map(([key, label]) => (
          <button key={key} type="button" className={route.tab === key ? "active" : ""} onClick={() => go(key)}>
            {label}
            {key === "incidents" && activeIncident && <span className="tab-count">{titleCase(activeIncident.status)}</span>}
          </button>
        ))}
      </nav>

      <main>
        <ErrorNote message={action.error} onDismiss={action.clearError} />
        {metrics.error && !metrics.data && <ErrorNote message={`Cannot reach the DataTraceMind API: ${metrics.error.message}`} />}
        {route.tab === "overview" && <Overview metrics={metrics.data} onOpenIncident={(id) => go("incidents", id)} />}
        {route.tab === "lab" && (
          <ScenarioLab onChanged={refreshAll} onOpenIncident={(id) => go("incidents", id)} activeIncident={activeIncident} />
        )}
        {route.tab === "incidents" && (
          <Incidents selectedId={route.id} onSelect={(id) => go("incidents", id)} agent={agent.data} onChanged={refreshAll} />
        )}
        {route.tab === "audit" && <Audit />}
      </main>
    </div>
  );
}

