.incident-summary { font-size: 15px; margin: 8px 0 4px; max-width: 90ch; }
.incident-actions { display: flex; flex-direction: column; align-items: flex-end; gap: 6px; max-width: 320px; text-align: right; font-size: 12.5px; }

.lifecycle { list-style: none; display: flex; flex-wrap: wrap; gap: 6px 4px; padding: 0; margin: 18px 0 2px; }
.step { display: inline-flex; align-items: center; gap: 6px; font-size: 12.5px; color: var(--text-muted); padding-right: 14px; }
.step-dot { width: 16px; height: 16px; border-radius: 50%; border: 1.5px solid var(--border); display: inline-grid; place-items: center; font-size: 10px; }
.step-done { color: var(--text-secondary); }
.step-done .step-dot { background: var(--good-wash); border-color: var(--good); color: var(--good-ink); }
.step-current { color: var(--text); font-weight: 650; }
.step-current .step-dot { border-color: var(--accent); background: var(--accent); }

.checks, .evidence, .timeline, .hypotheses, .checklist, .failures, .stages { list-style: none; padding: 0; margin: 0; }
.checks li, .evidence li { border-top: 1px solid var(--border); padding: 8px 0; }
.checks li:first-child, .evidence li:first-child { border-top: 0; }
.checks { margin-top: 10px; }
summary { cursor: pointer; }
details[open] > summary { margin-bottom: 8px; }
.json { background: var(--surface-sunken); border-radius: 8px; padding: 10px 12px; margin: 6px 0 0; overflow: auto; max-height: 340px; white-space: pre-wrap; overflow-wrap: anywhere; }
.evidence-cited { background: linear-gradient(to right, var(--active-wash), transparent 60%); margin: 0 -8px; padding-left: 8px !important; padding-right: 8px !important; border-radius: 6px; }

.timeline { display: grid; gap: 0; }
.event { display: grid; grid-template-columns: 76px 170px 1fr; gap: 10px; padding: 6px 0; border-top: 1px solid var(--border); font-size: 13px; }
.event:first-child { border-top: 0; }
.event-time { color: var(--text-muted); font-variant-numeric: tabular-nums; }
.event-agent { font-weight: 600; overflow-wrap: anywhere; }
.event-tool_call .event-agent { font-weight: 400; color: var(--text-muted); padding-left: 12px; }
.event-body { min-width: 0; overflow-wrap: anywhere; }
@media (max-width: 760px) { .event { grid-template-columns: 70px 1fr; } .event-body { grid-column: 1 / -1; } }

.root-cause { background: var(--good-wash); border-radius: 8px; padding: 12px 14px; margin-bottom: 12px; }
.root-cause p + p { margin-top: 6px; }
.hypotheses li { border-top: 1px solid var(--border); padding: 12px 0; }
.hypotheses li:first-child { border-top: 0; }
.hypotheses p { margin-top: 5px; max-width: 100ch; }
.hypothesis-head { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; font-size: 12.5px; }
.hypothesis-selected { border-left: 3px solid var(--good); padding-left: 12px !important; }
.meter { display: inline-block; width: 90px; height: 6px; border-radius: 3px; background: var(--active-wash); overflow: hidden; }
.meter span { display: block; height: 100%; background: var(--accent); border-radius: 3px; }
.evidence-links { font-size: 12.5px; }

/* --- Repair review --------------------------------------------------------- */

.stages { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 6px; }
.stages li { font-size: 12.5px; font-weight: 600; padding: 3px 10px; border-radius: 999px; border: 1px solid var(--border); color: var(--text-muted); text-transform: capitalize; }
.stages .stage-done { background: var(--good-wash); border-color: var(--good); color: var(--good-ink); }

.diff { background: var(--surface-sunken); border-radius: 8px; padding: 10px 0; margin: 0 0 12px; overflow-x: auto; }
.diff span { display: block; padding: 0 12px; white-space: pre; }
.diff-add { background: var(--diff-add); }
.diff-del { background: var(--diff-del); }
.diff-file { color: var(--text-muted); }
.diff-hunk { color: var(--accent); }

.kv { margin: 0; display: grid; gap: 10px; }
.kv > div { display: grid; grid-template-columns: 220px 1fr; gap: 12px; }
.kv dt { color: var(--text-muted); font-size: 13px; }
.kv dd { margin: 0; max-width: 100ch; }
@media (max-width: 760px) { .kv > div { grid-template-columns: 1fr; gap: 2px; } }

.checklist li { padding: 3px 0; font-size: 13px; }
.failures { margin: 8px 0; padding: 10px 14px; background: var(--critical-wash); color: var(--critical-ink); border-radius: 8px; }

.decision { margin-top: 20px; padding: 16px 18px; border: 1px solid var(--warning); background: var(--warning-wash); border-radius: 10px; }
.decision h3 { margin-top: 0; }
.decision-fields { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 12px; margin: 12px 0; }
.decision-fields label { display: grid; gap: 4px; font-size: 12.5px; font-weight: 600; color: var(--text-secondary); }
.decision-actions { display: flex; flex-wrap: wrap; gap: 10px; }
EOF
